17	fn two_zero_delay_timeouts_both_fire() {
18	    let clock = Rc::new(FixedClock::default());
19	    let context = &mut create_context(clock.clone());
20	
21	    run_test_actions_with(
22	        [
23	            TestAction::run(indoc! {r#"
24	                order = [];
25	                setTimeout(() => order.push(1), 0);
26	                setTimeout(() => order.push(2), 0);
27	            "#}),
28	            TestAction::inspect_context(move |ctx| {
29	                clock.forward(1);
30	                ctx.run_jobs().unwrap();
31	
32	                let order = ctx.global_object().get(js_str!("order"), ctx).unwrap();
33	                let order = order.as_object().unwrap();
34	                assert_eq!(
35	                    order.get(js_str!("length"), ctx).unwrap().as_i32(),
36	                    Some(2),
37	                    "both callbacks must fire"
38	                );
39	                assert_eq!(order.get(0usize, ctx).unwrap().as_i32(), Some(1));
40	                assert_eq!(order.get(1usize, ctx).unwrap().as_i32(), Some(2));
41	            }),
42	        ],
43	        context,
