use crate::job::{GenericJob, JobExecutor, NativeAsyncJob, SimpleJobExecutor};
use crate::{Context, JsValue, TestAction, run_test_actions_with};
use futures_lite::future;
use std::cell::{Cell, RefCell};
use std::pin::pin;
use std::rc::Rc;

#[test]
fn empty_event_loop_resolves_immediately() {
    let context = &mut Context::default();
    run_test_actions_with(
        [TestAction::inspect_context_async(|ctx| async move {
            let executor = ctx
                .downcast_job_executor::<SimpleJobExecutor>()
                .expect("default executor should be a SimpleJobExecutor");
            let ctx = RefCell::new(ctx);

            // With all queues empty and no async futures running, the loop must resolve.
            let result = future::poll_once(executor.run_jobs_async(&ctx)).await;
            assert!(
                matches!(result, Some(Ok(()))),
                "an empty event loop must resolve to Some(Ok(()))"
            );
        })],
        context,
    );
}

#[test]
fn one_shot_generic_job_runs_and_loop_terminates() {
    let context = &mut Context::default();
    run_test_actions_with(
        [TestAction::inspect_context_async(|ctx| async move {
            let realm = ctx.realm().clone();
            let executor = ctx
                .downcast_job_executor::<SimpleJobExecutor>()
                .expect("default executor should be a SimpleJobExecutor");

            let ran = Rc::new(Cell::new(false));
            {
                let ran = ran.clone();
                ctx.enqueue_job(
                    GenericJob::new(
                        move |_context| {
                            ran.set(true);
                            Ok(JsValue::undefined())
                        },
                        realm,
                    )
                    .into(),
                );
            }

            let ctx = RefCell::new(ctx);
            let result = future::poll_once(executor.run_jobs_async(&ctx)).await;
            assert!(ran.get(), "the generic job must run");
            assert!(
                matches!(result, Some(Ok(()))),
                "the loop must terminate once all jobs are done"
            );
        })],
        context,
    );
}

#[test]
fn async_job_keeps_loop_running_and_processes_later_generic_jobs() {
    let context = &mut Context::default();
    run_test_actions_with(
        [TestAction::inspect_context_async(|ctx| async move {
            let realm = ctx.realm().clone();
            let executor = ctx
                .downcast_job_executor::<SimpleJobExecutor>()
                .expect("default executor should be a SimpleJobExecutor");

            // An async job that never completes, always yielding back to the executor.
            ctx.enqueue_job(
                NativeAsyncJob::new(|_context| async {
                    loop {
                        future::yield_now().await;
                    }
                })
                .into(),
            );

            let ran = Rc::new(Cell::new(false));

            let ctx = RefCell::new(ctx);
            let mut fut = pin!(executor.run_jobs_async(&ctx));

            // The infinite async job keeps the event loop pending.
            assert!(
                future::poll_once(fut.as_mut()).await.is_none(),
                "loop must stay pending while an async future is running"
            );

            // Enqueue a generic job on the context between two polls of the same future.
            {
                let ran = ran.clone();
                ctx.borrow_mut().enqueue_job(
                    GenericJob::new(
                        move |_context| {
                            ran.set(true);
                            Ok(JsValue::undefined())
                        },
                        realm,
                    )
                    .into(),
                );
            }

            // The loop is still pending (the async future keeps running), but the generic
            // job enqueued between polls must have been executed on this poll.
            assert!(
                future::poll_once(fut.as_mut()).await.is_none(),
                "loop must stay pending while an async future is running"
            );
            assert!(
                ran.get(),
                "a generic job enqueued between polls must run on a subsequent poll"
            );
        })],
        context,
    );
}
