265	/// Regression test: a zero-delay `setInterval` with `StdClock` (real wall clock) must not
266	/// cause `run_jobs()` to spin forever.
267	///
268	/// The infinite loop required two conditions:
269	/// 1. The recurring job is re-enqueued at `now + 0ms = now`.
270	/// 2. `StdClock` advances by at least 1 ns between re-enqueue and the next termination check,
271	///    making the recurring job appear past-due, keeping `no_timeout_jobs_to_run = false`
272	///    forever.
273	///
274	/// The 5 ms sleep ensures the *initial* (non-recurring) job's timestamp is strictly in the
275	/// past so that `split_off` dispatches it on the first loop iteration and the recurring
276	/// re-schedule is what the termination check sees.
277	#[test]
278	fn set_interval_zero_delay_terminates_with_advancing_clock() {
279	    // ContextBuilder::default() uses StdClock (real wall clock, nanosecond resolution).
280	    let mut context = ContextBuilder::default().build().unwrap();
281	    interval::register(&mut context).unwrap();
282	
283	    context
284	        .eval(Source::from_bytes(
285	            // `var` (not `let`) so `count` is a property of the global object
286	            // and readable via `context.global_object().get(...)` after the run.
287	            "var count = 0; setInterval(() => { count++; }, 0);",
288	        ))
289	        .unwrap();
290	
291	    // Guarantee the initial job's scheduled instant is strictly in the past so the
292	    // split_off boundary does not hold it back.
293	    std::thread::sleep(std::time::Duration::from_millis(5));
294	
295	    // With the bug present this call never returned (100% CPU spin).
296	    context.run_jobs().unwrap();
297	
298	    // The interval must have fired at least once.
299	    let count = context
300	        .global_object()
